return items.map(item => {
  return {
    json: {
      memberId: item.json.memberId,
      memberName: item.json.name,
      clientCompanyId: item.json.clientCompanyId,
      clientName: item.json.clientName,
      body: item.json.body
    }
  };
});

// Parse Phoenix shift start to a UTC Date object (Phoenix = UTC-7, no DST)
function parseShiftStart(dateStr, localStartHHMM) {
  const [year, month, day] = dateStr.split('-').map(Number);
  const [startHour, startMinute] = localStartHHMM.split(':').map(Number);
  if (![year, month, day, startHour, startMinute].every(Number.isFinite)) {
    throw new Error(`Invalid date/time: date=${dateStr}, shiftStart=${localStartHHMM}`);
  }
  return new Date(Date.UTC(year, month - 1, day, startHour + 7, startMinute, 0));
}

// Add hours to a UTC Date and return a new Date
function addHours(utcDate, hours) {
  return new Date(utcDate.getTime() + hours * 3600000);
}

// Format a Date to ConnectWise-style ISO 8601 string
function isoZ(d) {
  return d.toISOString().replace('.000Z', 'Z');
}

// djb2 hash for deterministic day-over-day client rotation
function deterministicOffset(seed, modulo) {
  if (!modulo || modulo < 1) return 0;
  let hash = 0;
  const str = String(seed);
  for (let i = 0; i < str.length; i++) {
    hash = ((hash << 5) - hash) + str.charCodeAt(i);
    hash |= 0;
  }
  return Math.abs(hash) % modulo;
}

// Shared CW flags — same on every time entry
const CW_FLAGS = {
  addToDetailDescriptionFlag: false,
  addToInternalAnalysisFlag: false,
  addToResolutionFlag: false,
};

// Build the CW time entry body
function makeBody({ analyst, companyId, timeStart, timeEnd, actualHours, billableOption, notes, chargeToType, chargeToId }) {
  const body = {
    company: { id: companyId },
    chargeToType,
    member: { id: analyst.memberId },
    locationId: analyst.locationId,
    businessUnitId: analyst.businessUnitId,
    workType: { id: analyst.workTypeId },
    workRole: { id: analyst.workRoleId },
    timeStart,
    timeEnd,
    actualHours,
    billableOption,
    notes,
    ...CW_FLAGS,
  };
  if (chargeToId !== undefined && chargeToId !== null) body.chargeToId = chargeToId;
  return body;
}

// Build the n8n output item wrapper
function makeEntry(analyst, type, clientCompanyId, clientName, body) {
  return {
    json: {
      memberId: analyst.memberId,
      name: analyst.name,
      identifier: analyst.identifier,
      weekday: analyst.weekday,
      shiftName: analyst.shiftName,
      type,
      clientCompanyId,
      clientName,
      body,
    },
  };
}

// ── Input parsing ─────────────────────────────────────────────────────────────

const config = $json;

const date = config.date;
const roster = Array.isArray(config.members) ? config.members : [];
const shifts = Array.isArray(config.shifts) ? config.shifts : [];
const customers = Array.isArray(config.customers) ? config.customers.filter(c => c && c.billable) : [];
const dailyHours = config.dailyHours || { billable: 8, admin: 2 };

if (!date) throw new Error('Missing top-level date');
if (!roster.length) throw new Error('No roster members found');
if (!shifts.length) throw new Error('No shifts found');
if (!customers.length) throw new Error('No billable customers found');

const weekday = new Intl.DateTimeFormat('en-US', {
  timeZone: 'America/Phoenix',
  weekday: 'short',
}).format(new Date(`${date}T12:00:00Z`));

const rosterById = Object.fromEntries(roster.map(m => [String(m.memberId), m]));
const customerById = Object.fromEntries(customers.map(c => [String(c.companyId), c]));

// Pre-convert billing map IDs to strings once — they're static per run
const rawBillingMap = config.allowedBillingMap || {};
const allowedBillingMap = Object.fromEntries(
  Object.entries(rawBillingMap).map(([id, ids]) => [id, Array.isArray(ids) ? ids.map(String) : []])
);

// ── Build today's schedule ────────────────────────────────────────────────────

const scheduled = [];
for (const shift of shifts) {
  for (const sm of (shift.members || [])) {
    if (!Array.isArray(sm.days) || !sm.days.includes(weekday)) continue;
    const m = rosterById[String(sm.memberId)] || sm;
    scheduled.push({
      date,
      weekday,
      shiftName: shift.name,
      shiftStart: shift.start,
      memberId: m.memberId,
      identifier: m.identifier,
      name: m.name,
      workRoleId: m.workRoleId,
      workTypeId: m.workTypeId ?? config.workTypeId,
      locationId: m.locationId ?? config.locationId,
      businessUnitId: config.businessUnitId,
      chargeToType: config.chargeToType,
      chargeToId: config.chargeToId,
      internalCompanyId: config.companyId,
      dailyBillable: Number(m.dailyBillable ?? dailyHours.billable),
      dailyAdmin: Number(m.dailyAdmin ?? dailyHours.admin),
    });
  }
}

if (!scheduled.length) return [];

// Stable sort — precompute keys to avoid repeated OR-chain evaluation
scheduled.sort((a, b) => {
  const ka = a.identifier || a.name || String(a.memberId);
  const kb = b.identifier || b.name || String(b.memberId);
  return ka.localeCompare(kb);
});

// ── Generate CW time entries ──────────────────────────────────────────────────

const results = [];

for (const analyst of scheduled) {
  const memberKey = String(analyst.memberId);
  const allowedCustomers = (allowedBillingMap[memberKey] || [])
    .map(id => customerById[id])
    .filter(Boolean);

  const billableHours = analyst.dailyBillable;
  const adminHours = analyst.dailyAdmin;
  const shiftStart = parseShiftStart(analyst.date, analyst.shiftStart);
  const billableEnd = addHours(shiftStart, billableHours);

  if (allowedCustomers.length > 0 && billableHours > 0) {
    const client = allowedCustomers[deterministicOffset(`${date}-${memberKey}`, allowedCustomers.length)];

    // Billable: assigned customer for today
    // chargeToType/chargeToId stay as ChargeCode/35 — CW uses billableOption:'Billable'
    // to mark the entry as client-billable; company.id associates it with the customer
    results.push(makeEntry(
      analyst, 'billable', client.companyId, client.name,
      makeBody({ analyst, companyId: client.companyId, timeStart: isoZ(shiftStart), timeEnd: isoZ(billableEnd),
        actualHours: billableHours, billableOption: 'Billable', notes: `${analyst.shiftName} shift SOC coverage`,
        chargeToType: analyst.chargeToType || 'ChargeCode', chargeToId: analyst.chargeToId })
    ));

    // Admin: DoNotBill block immediately after billable shift — internal charge code
    if (adminHours > 0) {
      const adminEnd = addHours(billableEnd, adminHours);
      results.push(makeEntry(
        analyst, 'admin', analyst.internalCompanyId, 'Internal Admin',
        makeBody({ analyst, companyId: analyst.internalCompanyId, timeStart: isoZ(billableEnd), timeEnd: isoZ(adminEnd),
          actualHours: adminHours, billableOption: 'DoNotBill', notes: `${analyst.shiftName} shift admin`,
          chargeToType: analyst.chargeToType || 'ChargeCode', chargeToId: analyst.chargeToId })
      ));
    }
  } else {
    // No billing map entry: log full shift to internal company as DoNotBill
    const fullEnd = adminHours > 0 ? addHours(shiftStart, billableHours + adminHours) : billableEnd;
    results.push(makeEntry(
      analyst, 'admin', analyst.internalCompanyId, 'Internal Admin',
      makeBody({ analyst, companyId: analyst.internalCompanyId, timeStart: isoZ(shiftStart), timeEnd: isoZ(fullEnd),
        actualHours: billableHours + adminHours, billableOption: 'DoNotBill', notes: `${analyst.shiftName} shift internal SOC coverage`,
        chargeToType: analyst.chargeToType || 'ChargeCode', chargeToId: analyst.chargeToId })
    ));
  }
}

return results;
